import assert from "node:assert/strict";
import * as Path from "node:path";
import {
	Boot,
	Check,
	Finish,
	Fire,
	Furnace,
	Group,
	Ledger,
	LedgerFile,
	LoggerLines,
	MakeContext,
	MakeCounter,
	ProbeState,
	Root,
	SeamStub,
} from "../Harness.js";

/**
 * @module Test
 *
 * One singular test of the activation, wire, and attach postures.
 *
 * @remarks
 *
 * The activation posture (the ledger byte-shape regex + the State.Module logger
 * prefix), the factory-built shared state shape with the cargo module fields,
 * the wire posture (exactly one fiber-owned fs/observed registration + the State
 * builder's P10 volatile-update refresh), and the attach posture (the P1/P2/P5
 * effect labels + the P1 root jobs controller).
 *
 * Runs standalone (`node Target/Test/State-And-Activation/Test.js`) AND under
 * the aggregate (`Maintain/Run/Smokes/Index.mjs` spawns it). Unit smoke of
 * `@playform/hook-dsh-cargo-governor`.
 */
export const runTest = async (): Promise<number> => {
	const Count = MakeCounter();

	// Group: the activation posture.
	{
		const dir = Group("act");
		void dir;
		const m = MakeContext({ services: { subprocess: SeamStub() } });
		m.ctx.pluginFactory = Furnace;
		m.ledger = LedgerFile("act");
		Boot(m);
		const lines = Ledger(m.ledger);
		Check(Count, "activation: ledger byte-shape + `hook-dsh-governor-cargo: ` logger prefix", () => {
			assert.equal(lines.length, 1, "exactly one activation line");
			assert.match(
				lines[0]!,
				/^activated \(cargo flavor, logFile=.*cargo-smoke-.*\.log, updateMode=cargo, cargoBin=cargo, exclude=\[node_modules, \.git, \.dsh, \.pnpm, \.store, DeepSeek Harness\.app\], policyFile=\(discovery\), keepFile=\(discovery\)\)$/,
				"the CARGO MODULE activation string byte-shape",
			);
			assert.equal(
				LoggerLines.info.at(-1),
				`hook-dsh-governor-cargo: ${lines[0]}`,
				"logger prefix = State.Module",
			);
		});
	}
	// Group: the factory-built shared state shape.
	{
		const m = MakeContext({ services: { subprocess: SeamStub() } });
		m.ctx.pluginFactory = Furnace;
		m.ledger = LedgerFile("state");
		Boot(m);
		const S = ProbeState;
		Check(Count, "state: factory-built shared shape + module fields + activation journal record", () => {
			assert.equal(S.Module, "hook-dsh-governor-cargo");
			assert.equal(S.PolicyName, "pin-policy.json", "the factory's keep sidecar name");
			assert.equal(S.Policy, "");
			assert.equal(S.Ledger, m.ledger);
			assert.equal(S.Enabled, true);
			assert.equal(S.On, true, "the master switch (enabled) mapped by the setup map");
			assert.deepEqual(S.Tool, ["write", "edit", "str_replace_editor", "raw-write"]);
			assert.deepEqual(S.List, [
				"node_modules",
				".git",
				".dsh",
				".pnpm",
				".store",
				"DeepSeek Harness.app",
			]);
			assert.equal(S.Strict, false);
			assert.equal(S.Wait, 0);
			assert.equal(S.Limit, 3);
			assert.equal(S.CargoBin, "cargo");
			assert.equal(S.KeepFile, "");
			assert.equal(S.Mode, "cargo");
			assert.ok(
				S.Stash instanceof Map &&
					S.Inflight instanceof Map &&
					S.Seams instanceof Map &&
					Array.isArray(S.Queue),
			);
			assert.ok(S.Stamp instanceof Map && S.Set instanceof Set && S.Count instanceof Map);
			assert.equal(S.Subprocess, m.services.subprocess, "the P9 seam probed at State build");
			assert.equal(typeof S.Journal, "function", "the P5 journal sink present");
		});
	}
	// Group: the wire posture.
	{
		const m = MakeContext({ services: { subprocess: SeamStub() } });
		m.ctx.pluginFactory = Furnace;
		m.ledger = LedgerFile("wire");
		Boot(m);
		Check(
			Count,
			"wire: exactly one fiber-owned fs/observed registration, plus the P10 volatile-update refresh",
			() => {
				assert.equal(
					m.captured.events.filter((e: any) => e[0] === "fs/observed").length,
					1,
					"exactly one fs/observed listener (the factory's Wire)",
				);
				assert.equal(
					m.captured.events.filter((e: any) => e[0] !== "fs/observed").length,
					1,
					"one other hook: the State builder's P10 loader/volatile-update refresh (never fs/write-intent, never tools/*)",
				);
			},
		);
	}
	// Group: the attach posture.
	{
		const m = MakeContext({ services: { subprocess: SeamStub() } });
		m.ctx.pluginFactory = Furnace;
		m.ledger = LedgerFile("attach");
		Boot(m);
		const m2 = MakeContext({
			services: {
				subprocess: SeamStub(),
				jobs: {
					attachController: (n: string) => {
						m2.captured.controllers.push(n);
						return () => {};
					},
				},
			},
		});
		m2.ctx.pluginFactory = Furnace;
		m2.ledger = LedgerFile("attach2");
		Boot(m2);
		Check(Count, "attach: P1/P2/P5 effect labels + P1 root jobs controller", () => {
			assert.deepEqual(
				m.captured.effects.map((e: any) => e[0]),
				[
					"hook-dsh-governor-cargo-jobs",
					"hook-dsh-governor-cargo-inflight",
					"hook-dsh-governor-cargo-storage",
				],
			);
			assert.deepEqual(
				m.captured.controllers,
				[],
				"no jobs service in this scenario \u2192 no controller",
			);
			assert.deepEqual(
				m2.captured.controllers,
				["hook-dsh-governor-cargo"],
				"P1 attaches the root controller",
			);
		});
	}
	// Group: the disabled mount (enabled=false) - the LIVE disabled posture. A
	// disabled mount registers EVERYTHING (no early return) and its only
	// mount-time effect is the byte-exact disabled ledger line instead of the
	// activation proof; every surface then checks the flag at CALL time and
	// passes through with zero new lines, and a volatile flip acts on the very
	// next call in both directions.
	{
		const m = MakeContext({ services: { subprocess: SeamStub() } });
		m.ctx.pluginFactory = Furnace;
		m.ledger = LedgerFile("disabled");
		Boot(m, { enabled: false });
		const S = ProbeState;
		const Excluded = {
			displayPath: Path.join(Root, "node_modules", "probe", "Cargo.toml"),
		};
		Check(
			Count,
			"disabled mount: every surface still registers and the ledger line is the byte-exact disabled line (no early return)",
			() => {
				assert.equal(S.On, false, "the disabled mount's master switch");
				assert.deepEqual(
					Ledger(m.ledger),
					["disabled (enabled=false)"],
					"the ONLY ledger line is the byte-exact disabled line (no activation proof)",
				);
				assert.equal(
					m.captured.events.filter((e: any) => e[0] === "fs/observed").length,
					1,
					"the fs/observed listener STILL registered (no early return)",
				);
				assert.deepEqual(
					m.captured.effects.map((e: any) => e[0]),
					[
						"hook-dsh-governor-cargo-jobs",
						"hook-dsh-governor-cargo-inflight",
						"hook-dsh-governor-cargo-storage",
					],
					"the P1/P2/P5 lifecycle effects STILL registered",
				);
				assert.equal(
					LoggerLines.info.at(-1),
					`hook-dsh-governor-cargo: ${Ledger(m.ledger)[0]}`,
					"logger prefix = State.Module",
				);
			},
		);
		{
			const Silent = Ledger(m.ledger).length;
			Check(Count, "disabled mount: a call passes through with ZERO new ledger lines", () => {
				// The excluded target is the deterministic fs-free probe: an ENABLED
				// listener would land the module's `skipped (excluded) ...` line; a
				// disabled one must not move the ledger at all.
				Fire(m, { targetKey: "disabled-probe", ...Excluded }, "v-disabled-1");
				assert.equal(
					Ledger(m.ledger).length,
					Silent,
					"the disabled call did nothing (no exclusion line, no gate line)",
				);
			});
			Check(Count, "disabled mount: flipping enabled acts on the very next call - and back", () => {
				// Flip ON: the very next call runs the gates - the excluded target
				// lands the module's exclusion line (deterministic, fs-free).
				S.On = true;
				Fire(m, { targetKey: "disabled-probe", ...Excluded }, "v-disabled-1");
				const lines = Ledger(m.ledger);
				assert.equal(lines.length, Silent + 1, "the flipped-on call ran the gates (one new line)");
				assert.ok(
					lines.at(-1)!.startsWith("skipped (excluded) "),
					"the pass really ran (the module's exclusion line)",
				);
				// Flip OFF: the next call is silent again (a fresh version token
				// keeps the Stash gate out of the way - the master switch is the
				// only gate standing).
				S.On = false;
				Fire(m, { targetKey: "disabled-probe-2", ...Excluded }, "v-disabled-2");
				assert.equal(Ledger(m.ledger).length, Silent + 1, "the flipped-back call is silent again");
			});
		}
	}
	return Finish(Count, "State-And-Activation");
};

// Standalone entry: `node Target/Test/State-And-Activation/Test.js`.
const InvokedDirectly =
	process.argv[1] !== undefined &&
	import.meta.url === (await import("node:url")).pathToFileURL(process.argv[1]).href;
if (InvokedDirectly) {
	const Pass = await runTest();
	console.log(`${Pass} PASS - State-And-Activation`);
}
